---
graph TD;
	__start__([<p>__start__</p>]):::first
	ingest(ingest)
	extract_claims(extract_claims)
	preapproved_filter(preapproved_filter)
	substantiation(substantiation)
	off_label(off_label)
	presentation(presentation)
	house_rules(house_rules)
	consolidate(consolidate)
	risk_judgement(risk_judgement)
	route(route)
	human_review(human_review)
	finalize(finalize)
	__end__([<p>__end__</p>]):::last
	__start__ --> ingest;
	consolidate --> risk_judgement;
	extract_claims --> preapproved_filter;
	house_rules --> consolidate;
	human_review --> finalize;
	ingest --> extract_claims;
	off_label --> consolidate;
	preapproved_filter -.-> consolidate;
	preapproved_filter -.-> house_rules;
	preapproved_filter -.-> off_label;
	preapproved_filter -.-> presentation;
	preapproved_filter -.-> substantiation;
	presentation --> consolidate;
	risk_judgement --> route;
	route --> human_review;
	substantiation --> consolidate;
	finalize --> __end__;
	classDef default fill:#f2f0ff,line-height:1.2
	classDef first fill-opacity:0
	classDef last fill:#bfb6fc
